+%   [x_set y_set z_set numSamples] = ReadFiles(folder);
+%
+%   2) explicit plot
+%   folder = 'Data\MODELS\Climb_stairs_MODEL\';
+%   [x_set y_set z_set numSamples] = ReadFiles(folder,1);
+%
+%   3) no plot
+%   folder = 'Data\MODELS\Climb_stairs_MODEL\';
+%   [x_set y_set z_set numSamples] = ReadFiles(folder,0);
